import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { Camera, Save, AlertCircle, CheckCircle } from 'lucide-react';
import { professeurAPI } from '../../services/api';

/**
 * VueProfilProfesseur - Gestion du profil du professeur
 */
const VueProfilProfesseur = ({ user, profil, onRefresh }) => {
  const [formData, setFormData] = useState({
    nomComplet: profil?.nomComplet || '',
    email: profil?.email || '',
    numeroTelephone: profil?.numeroTelephone || '',
  });
  const [saving, setSaving] = useState(false);
  const [message, setMessage] = useState(null);
  const [photoFile, setPhotoFile] = useState(null);

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handlePhotoSelect = (e) => {
    const file = e.target.files?.[0];
    if (file) {
      setPhotoFile(file);
      setMessage({ type: 'info', text: 'Photo sélectionnée. Cliquez sur Enregistrer pour confirmer.' });
    }
  };

  const handleSave = async () => {
    try {
      setSaving(true);
      setMessage(null);

      // Mettre à jour le profil
      await professeurAPI.updateProfil(user.id, formData);

      // Upload la photo si fournie
      if (photoFile) {
        await professeurAPI.uploadPhoto(user.id, photoFile);
        setPhotoFile(null);
      }

      setMessage({ type: 'success', text: 'Profil mis à jour avec succès!' });
      onRefresh?.();
    } catch (error) {
      console.error('Erreur lors de la sauvegarde:', error);
      setMessage({ type: 'error', text: 'Erreur lors de la sauvegarde du profil.' });
    } finally {
      setSaving(false);
    }
  };

  return (
    <motion.div
      className="vue-profil"
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
    >
      <h2>Mon Profil Professionnel</h2>

      {/* Messages */}
      {message && (
        <motion.div
          className={`message-box ${message.type}`}
          initial={{ opacity: 0, y: -10 }}
          animate={{ opacity: 1, y: 0 }}
        >
          {message.type === 'success' && <CheckCircle size={20} />}
          {message.type === 'error' && <AlertCircle size={20} />}
          {message.type === 'info' && <AlertCircle size={20} />}
          <span>{message.text}</span>
        </motion.div>
      )}

      <div className="profil-container">
        {/* Section Photo */}
        <motion.div
          className="photo-section"
          initial={{ opacity: 0, x: -20 }}
          animate={{ opacity: 1, x: 0 }}
        >
          <div className="photo-frame">
            {profil?.photoUrl ? (
              <img src={profil.photoUrl} alt="Profil" />
            ) : (
              <div className="photo-placeholder">No Photo</div>
            )}
          </div>
          <label className="photo-upload-btn">
            <Camera size={20} />
            <span>Changer la photo</span>
            <input
              type="file"
              accept="image/*"
              onChange={handlePhotoSelect}
              hidden
            />
          </label>
          {photoFile && (
            <div className="selected-photo-name">
              ✓ {photoFile.name}
            </div>
          )}
        </motion.div>

        {/* Formulaire */}
        <motion.div
          className="form-section"
          initial={{ opacity: 0, x: 20 }}
          animate={{ opacity: 1, x: 0 }}
        >
          <div className="form-group">
            <label htmlFor="nomComplet">Nom Complet</label>
            <input
              id="nomComplet"
              type="text"
              name="nomComplet"
              value={formData.nomComplet}
              onChange={handleInputChange}
              placeholder="Entrez votre nom complet"
            />
          </div>

          <div className="form-group">
            <label htmlFor="email">Email</label>
            <input
              id="email"
              type="email"
              name="email"
              value={formData.email}
              onChange={handleInputChange}
              placeholder="Entrez votre email"
            />
          </div>

          <div className="form-group">
            <label htmlFor="numeroTelephone">Téléphone</label>
            <input
              id="numeroTelephone"
              type="tel"
              name="numeroTelephone"
              value={formData.numeroTelephone}
              onChange={handleInputChange}
              placeholder="Entrez votre numéro"
              disabled
            />
          </div>

          {profil?.universite && (
            <div className="form-group">
              <label>Université</label>
              <input
                type="text"
                value={profil.universite.nom}
                disabled
              />
            </div>
          )}

          <button
            className="btn-primary"
            onClick={handleSave}
            disabled={saving}
          >
            {saving ? (
              <>
                <span className="spinner"></span> Enregistrement...
              </>
            ) : (
              <>
                <Save size={20} /> Enregistrer
              </>
            )}
          </button>
        </motion.div>
      </div>
    </motion.div>
  );
};

export default VueProfilProfesseur;
