import React, { useState, useEffect } from 'react';
import { useToast } from '../../hooks/useToast';
import { motion, AnimatePresence } from 'framer-motion';
import { Send, Users, BookOpen, Filter, CheckSquare, Square, ArrowRight, ArrowLeft, Loader } from 'lucide-react';
import { professeurAPI, academicAPI } from '../../services/api';

/**
 * VueDistribution — Distribution de cours aux étudiants (3 étapes)
 * Étape 1 : Sélectionner la ressource (cours)
 * Étape 2 : Filtrer les étudiants (Faculté → Filière → Niveau)
 * Étape 3 : Confirmer et distribuer
 */
const VueDistribution = ({ user, cours = [], onRefresh }) => {
  const { showToast, ToastUI } = useToast();
  const [step, setStep]                       = useState(1);
  const [selectedResource, setSelectedResource] = useState(null);
  const [facultes, setFacultes]               = useState([]);
  const [filieres, setFilieres]               = useState([]);
  const [selectedFaculte, setSelectedFaculte] = useState('');
  const [selectedFiliere, setSelectedFiliere] = useState('');
  const [selectedNiveau, setSelectedNiveau]   = useState('');
  const [students, setStudents]               = useState([]);
  const [selectedStudents, setSelectedStudents] = useState(new Set());
  const [loadingFacultes, setLoadingFacultes] = useState(false);
  const [loadingFilieres, setLoadingFilieres] = useState(false);
  const [loadingStudents, setLoadingStudents] = useState(false);
  const [distributing, setDistributing]       = useState(false);

  const NIVEAUX = ['L1', 'L2', 'L3', 'M1', 'M2', 'D1', 'D2', 'D3'];

  // ── Charger facultés de l'université du prof ─────────────
  useEffect(() => {
    const univId = user?.universite?.id;
    if (!univId) return;
    setLoadingFacultes(true);
    academicAPI.getFacultesByUniv(univId)
      .then(r => setFacultes(r.data || []))
      .catch(() => {})
      .finally(() => setLoadingFacultes(false));
  }, [user]);

  // ── Charger filières quand faculté change ────────────────
  useEffect(() => {
    if (!selectedFaculte) { setFilieres([]); setSelectedFiliere(''); return; }
    setLoadingFilieres(true);
    academicAPI.getFilieres(selectedFaculte)
      .then(r => setFilieres(r.data || []))
      .catch(() => {})
      .finally(() => setLoadingFilieres(false));
  }, [selectedFaculte]);

  // ── Chercher étudiants quand un filtre change ────────────
  const handleSearchStudents = async () => {
    try {
      setLoadingStudents(true);
      setSelectedStudents(new Set());
      const res = await professeurAPI.filtrerEtudiants(
        user.id,
        selectedFaculte || null,
        selectedFiliere || null,
        selectedNiveau  || null
      );
      setStudents(res.data || []);
      if ((res.data || []).length === 0) {
        showToast('Aucun étudiant trouvé pour ces critères', 'info');
      }
    } catch (err) {
      console.error(err);
      showToast('Erreur lors du chargement des étudiants', 'error');
    } finally {
      setLoadingStudents(false);
    }
  };

  // ── Sélection/désélection ────────────────────────────────
  const toggleStudent = (id) => {
    setSelectedStudents(prev => {
      const next = new Set(prev);
      next.has(id) ? next.delete(id) : next.add(id);
      return next;
    });
  };

  const selectAll = () => {
    setSelectedStudents(new Set(students.map(s => s.id)));
  };
  const deselectAll = () => setSelectedStudents(new Set());

  // ── Distribution ─────────────────────────────────────────
  const handleDistribute = async () => {
    try {
      setDistributing(true);
      await professeurAPI.distribuerCours(selectedResource.id, Array.from(selectedStudents));
      showToast(`✅ Cours distribué à ${selectedStudents.size} étudiant(s) !`);
      // Réinitialiser
      setStep(1);
      setSelectedResource(null);
      setSelectedStudents(new Set());
      setStudents([]);
      onRefresh?.();
    } catch (err) {
      console.error(err);
      showToast('Erreur lors de la distribution', 'error');
    } finally {
      setDistributing(false);
    }
  };

  return (
    <motion.div className="vue-distribution" initial={{ opacity: 0 }} animate={{ opacity: 1 }}>
      {ToastUI}

      {/* ── Header ── */}
      <div className="vue-header">
        <h2>Distribuer aux Étudiants</h2>
      </div>

      {/* ── Stepper ── */}
      <div className="stepper">
        {['Choisir le cours', 'Sélectionner étudiants', 'Confirmer'].map((label, i) => (
          <div
            key={i}
            className={`step-item ${step === i + 1 ? 'active' : step > i + 1 ? 'done' : ''}`}
          >
            <div className="step-circle">{step > i + 1 ? '✓' : i + 1}</div>
            <span className="step-label">{label}</span>
            {i < 2 && <ArrowRight size={14} className="step-arrow" />}
          </div>
        ))}
      </div>

      {/* ════════════════════ ÉTAPE 1 ════════════════════ */}
      <AnimatePresence mode="wait">
        {step === 1 && (
          <motion.div
            key="step1"
            className="distribution-step"
            initial={{ opacity: 0, x: 30 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: -30 }}
          >
            <h3>
              <BookOpen size={18} style={{ marginRight: 8 }} />
              Sélectionner un cours à distribuer
            </h3>

            {cours.length === 0 ? (
              <div className="empty-state">
                <BookOpen size={40} />
                <p>Aucun cours disponible</p>
                <small>Créez d'abord un cours dans "Mes Cours"</small>
              </div>
            ) : (
              <div className="resource-list">
                {cours.map(c => (
                  <motion.div
                    key={c.id}
                    className={`resource-item ${selectedResource?.id === c.id ? 'selected' : ''}`}
                    whileHover={{ scale: 1.01 }}
                    onClick={() => { setSelectedResource(c); setStep(2); }}
                  >
                    <div className="resource-info">
                      <h4>{c.titre}</h4>
                      <p>{c.matiere?.nom || '—'} · {c.niveau || 'Tous niveaux'}</p>
                    </div>
                    <button className="btn-primary" onClick={e => { e.stopPropagation(); setSelectedResource(c); setStep(2); }}>
                      Sélectionner <ArrowRight size={14} />
                    </button>
                  </motion.div>
                ))}
              </div>
            )}
          </motion.div>
        )}

        {/* ════════════════════ ÉTAPE 2 ════════════════════ */}
        {step === 2 && (
          <motion.div
            key="step2"
            className="distribution-step"
            initial={{ opacity: 0, x: 30 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: -30 }}
          >
            <h3>
              <Filter size={18} style={{ marginRight: 8 }} />
              Filtrer et sélectionner les étudiants
            </h3>

            <div className="selected-resource-badge">
              <BookOpen size={14} />
              <span>Cours : <strong>{selectedResource?.titre}</strong></span>
            </div>

            {/* Filtres en cascade */}
            <div className="filter-cascade">
              {/* Faculté */}
              <div className="form-group">
                <label>Faculté</label>
                <select
                  value={selectedFaculte}
                  onChange={e => { setSelectedFaculte(e.target.value); setSelectedFiliere(''); }}
                  disabled={loadingFacultes}
                >
                  <option value="">— Toutes les facultés —</option>
                  {facultes.map(f => <option key={f.id} value={f.id}>{f.nom}</option>)}
                </select>
              </div>

              {/* Filière */}
              <div className="form-group">
                <label>Filière</label>
                <select
                  value={selectedFiliere}
                  onChange={e => setSelectedFiliere(e.target.value)}
                  disabled={loadingFilieres || !selectedFaculte}
                >
                  <option value="">— Toutes les filières —</option>
                  {filieres.map(f => <option key={f.id} value={f.id}>{f.nom}</option>)}
                </select>
              </div>

              {/* Niveau */}
              <div className="form-group">
                <label>Niveau</label>
                <select
                  value={selectedNiveau}
                  onChange={e => setSelectedNiveau(e.target.value)}
                >
                  <option value="">— Tous les niveaux —</option>
                  {['L1', 'L2', 'L3', 'M1', 'M2', 'D1', 'D2', 'D3'].map(n => (
                    <option key={n} value={n}>{n}</option>
                  ))}
                </select>
              </div>

              <button
                className="btn-primary"
                onClick={handleSearchStudents}
                disabled={loadingStudents}
              >
                {loadingStudents ? <Loader size={16} className="spinner" /> : <Users size={16} />}
                {loadingStudents ? 'Chargement…' : 'Rechercher'}
              </button>
            </div>

            {/* Liste étudiants */}
            {students.length > 0 && (
              <>
                <div className="students-header">
                  <span style={{ fontSize: '0.85rem', color: '#475569' }}>
                    {students.length} étudiant(s) trouvé(s) · {selectedStudents.size} sélectionné(s)
                  </span>
                  <div style={{ display: 'flex', gap: 8 }}>
                    <button className="btn-secondary small" onClick={selectAll}>
                      <CheckSquare size={14} /> Tous
                    </button>
                    <button className="btn-secondary small" onClick={deselectAll}>
                      <Square size={14} /> Aucun
                    </button>
                  </div>
                </div>
                <div className="students-list">
                  {students.map(s => (
                    <label key={s.id} className={`student-checkbox ${selectedStudents.has(s.id) ? 'checked' : ''}`}>
                      <input
                        type="checkbox"
                        checked={selectedStudents.has(s.id)}
                        onChange={() => toggleStudent(s.id)}
                      />
                      <div className="student-info">
                        <span className="student-name">{s.nomComplet}</span>
                        <span className="student-meta">
                          {s.filiere?.nom || '—'} · {s.niveau || '—'}
                        </span>
                      </div>
                    </label>
                  ))}
                </div>
              </>
            )}

            <div className="step-actions">
              <button className="btn-secondary" onClick={() => setStep(1)}>
                <ArrowLeft size={14} /> Retour
              </button>
              <button
                className="btn-primary"
                onClick={() => setStep(3)}
                disabled={selectedStudents.size === 0}
              >
                Suivant — {selectedStudents.size} sélectionné(s) <ArrowRight size={14} />
              </button>
            </div>
          </motion.div>
        )}

        {/* ════════════════════ ÉTAPE 3 ════════════════════ */}
        {step === 3 && (
          <motion.div
            key="step3"
            className="distribution-step"
            initial={{ opacity: 0, x: 30 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: -30 }}
          >
            <h3>
              <Send size={18} style={{ marginRight: 8 }} />
              Confirmer la distribution
            </h3>

            <div className="confirmation-box">
              <div className="confirm-row">
                <span className="confirm-label">📚 Cours</span>
                <strong>{selectedResource?.titre}</strong>
              </div>
              <div className="confirm-row">
                <span className="confirm-label">🎓 Étudiants</span>
                <strong>{selectedStudents.size} étudiant(s)</strong>
              </div>
              <div className="confirm-row">
                <span className="confirm-label">📌 Matière</span>
                <span>{selectedResource?.matiere?.nom || '—'}</span>
              </div>
            </div>

            <div className="info-box" style={{
              background: 'rgba(16,185,129,0.07)',
              border: '1px solid rgba(16,185,129,0.2)',
              borderRadius: 10, padding: '12px 16px',
              color: '#34D399', fontSize: '0.8rem'
            }}>
              ✅ Le cours sera rendu accessible à ces {selectedStudents.size} étudiants.
              Une notification leur sera envoyée.
            </div>

            <div className="step-actions">
              <button className="btn-secondary" onClick={() => setStep(2)} disabled={distributing}>
                <ArrowLeft size={14} /> Retour
              </button>
              <button className="btn-primary" onClick={handleDistribute} disabled={distributing}>
                {distributing
                  ? <><Loader size={16} className="spinner" /> Distribution…</>
                  : <><Send size={16} /> Distribuer maintenant</>
                }
              </button>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </motion.div>
  );
};

export default VueDistribution;
