import React, { useState, useEffect } from 'react';
import { AlertCircle, Loader, FileText, Image as ImageIcon, CheckCircle, Clock, MoreVertical, MessageSquare } from 'lucide-react';
import { submissionsAPI } from '../services/api';

/**
 * SubmissionsList - Affiche les soumissions en attente de correction pour les profs
 */
const SubmissionsList = ({ professeurId, epreuveId }) => {
  const [submissions, setSubmissions] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [filter, setFilter] = useState('SOUMIS'); // SOUMIS, EN_CORRECTION, CORRIGE
  const [expandedId, setExpandedId] = useState(null);
  const [correctionData, setCorrectionData] = useState({});

  useEffect(() => {
    loadSubmissions();
  }, [epreuveId]);

  const loadSubmissions = async () => {
    try {
      setLoading(true);
      const res = epreuveId
        ? await submissionsAPI.getSubmissionsEpreuve(epreuveId)
        : await submissionsAPI.getSubmissionsEnAttente(professeurId);
      setSubmissions(res.data || []);
    } catch (err) {
      setError('Erreur lors du chargement des soumissions');
    } finally {
      setLoading(false);
    }
  };

  const handleMarquerEnCorrection = async (submissionId) => {
    try {
      await submissionsAPI.marquerEnCorrection(submissionId);
      await loadSubmissions();
    } catch (err) {
      setError('Erreur lors de la mise à jour');
    }
  };

  const handleTerminerCorrection = async (submissionId) => {
    const data = correctionData[submissionId];
    if (!data || !data.retour) {
      setError('Le retour est requis');
      return;
    }

    try {
      await submissionsAPI.terminerCorrection(submissionId, data.retour, data.note);
      await loadSubmissions();
      setCorrectionData({ ...correctionData, [submissionId]: null });
      setExpandedId(null);
    } catch (err) {
      setError('Erreur lors de la soumission de la correction');
    }
  };

  const filtered = submissions.filter(sub => {
    if (filter === 'all') return true;
    return sub.statut === filter;
  });

  const getStatutBadge = (statut) => {
    const styles = {
      SOUMIS: { bg: '#fef3c7', color: '#92400e', label: '📥 Soumis' },
      EN_CORRECTION: { bg: '#dbeafe', color: '#1e40af', label: '⏳ En correction' },
      CORRIGE: { bg: '#f0fdf4', color: '#15803d', label: '✅ Corrigé' }
    };
    const style = styles[statut] || styles.SOUMIS;
    return (
      <span style={{
        background: style.bg,
        color: style.color,
        padding: '6px 12px',
        borderRadius: '6px',
        fontSize: '0.85rem',
        fontWeight: 700
      }}>
        {style.label}
      </span>
    );
  };

  if (loading) return <div style={{ padding: '20px', textAlign: 'center' }}><Loader className="spinner" /> Chargement...</div>;

  return (
    <div style={{ padding: '20px' }}>
      <div style={{ marginBottom: '20px' }}>
        <h3 style={{ margin: '0 0 10px 0', fontSize: '1.2rem', fontWeight: 700 }}>📋 Soumissions à Corriger</h3>
        <p style={{ margin: 0, color: '#666', fontSize: '0.9rem' }}>
          Gérez et corrigez les soumissions de vos étudiants
        </p>
      </div>

      {error && (
        <div style={{
          background: '#fee',
          padding: '12px 15px',
          borderRadius: '8px',
          marginBottom: '15px',
          color: '#c33',
          display: 'flex',
          gap: '10px'
        }}>
          <AlertCircle size={18} style={{ flexShrink: 0 }} />
          {error}
        </div>
      )}

      {/* Filtres */}
      <div style={{ display: 'flex', gap: '10px', marginBottom: '20px', flexWrap: 'wrap' }}>
        {['SOUMIS', 'EN_CORRECTION', 'CORRIGE', 'all'].map(f => (
          <button
            key={f}
            onClick={() => setFilter(f)}
            style={{
              padding: '8px 16px',
              background: filter === f ? '#3b82f6' : '#f0f0f0',
              color: filter === f ? 'white' : '#333',
              border: 'none',
              borderRadius: '6px',
              cursor: 'pointer',
              fontWeight: 600,
              transition: 'all 0.2s'
            }}
            onMouseEnter={(e) => !filter === f && (e.target.style.background = '#e0e0e0')}
            onMouseLeave={(e) => !filter === f && (e.target.style.background = '#f0f0f0')}
          >
            {f === 'SOUMIS' && '📥 À corriger'}
            {f === 'EN_CORRECTION' && '⏳ En cours'}
            {f === 'CORRIGE' && '✅ Corrigés'}
            {f === 'all' && '📋 Tous'}
          </button>
        ))}
      </div>

      {/* Liste */}
      {filtered.length === 0 ? (
        <div style={{
          padding: '40px 20px',
          textAlign: 'center',
          color: '#999',
          background: '#f8f9fa',
          borderRadius: '8px'
        }}>
          <Clock size={40} style={{ margin: '0 auto 15px', display: 'block', opacity: 0.5 }} />
          <p style={{ margin: 0, fontWeight: 600 }}>Aucune soumission pour ce filtre</p>
        </div>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
          {filtered.map(sub => (
            <div
              key={sub.id}
              style={{
                background: 'white',
                border: '1px solid #e5e7eb',
                borderRadius: '10px',
                overflow: 'hidden'
              }}
            >
              {/* En-tête */}
              <div
                onClick={() => setExpandedId(expandedId === sub.id ? null : sub.id)}
                style={{
                  padding: '15px',
                  display: 'flex',
                  justifyContent: 'space-between',
                  alignItems: 'center',
                  cursor: 'pointer',
                  background: expandedId === sub.id ? '#f9fafb' : 'white',
                  borderBottom: expandedId === sub.id ? '1px solid #e5e7eb' : 'none'
                }}
                onMouseEnter={(e) => e.currentTarget.style.background = '#f9fafb'}
                onMouseLeave={(e) => e.currentTarget.style.background = expandedId === sub.id ? '#f9fafb' : 'white'}
              >
                <div style={{ flex: 1 }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '12px', marginBottom: '8px' }}>
                    <strong>{sub.etudiant?.nomComplet || 'Étudiant'}</strong>
                    {getStatutBadge(sub.statut)}
                  </div>
                  <p style={{ margin: '0', color: '#666', fontSize: '0.9rem' }}>
                    {sub.epreuve?.titre || 'Épreuve'}
                  </p>
                </div>
                <MoreVertical size={20} style={{ color: '#999' }} />
              </div>

              {/* Détails */}
              {expandedId === sub.id && (
                <div style={{ padding: '15px', background: '#f9fafb', borderTop: '1px solid #e5e7eb' }}>
                  {/* Fichiers */}
                  <div style={{ marginBottom: '15px' }}>
                    <h4 style={{ margin: '0 0 10px 0', fontSize: '0.95rem', fontWeight: 700 }}>📎 Fichiers soumis</h4>
                    <div style={{ display: 'flex', gap: '10px', flexWrap: 'wrap' }}>
                      {sub.fichierEpreuve && (
                        <a
                          href={sub.fichierEpreuve}
                          target="_blank"
                          rel="noreferrer"
                          style={{
                            display: 'flex',
                            alignItems: 'center',
                            gap: '8px',
                            padding: '8px 12px',
                            background: '#dbeafe',
                            color: '#1e40af',
                            textDecoration: 'none',
                            borderRadius: '6px',
                            fontWeight: 600,
                            fontSize: '0.9rem'
                          }}
                        >
                          <FileText size={16} /> Épreuve
                        </a>
                      )}
                      {sub.imageSolution && (
                        <a
                          href={sub.imageSolution}
                          target="_blank"
                          rel="noreferrer"
                          style={{
                            display: 'flex',
                            alignItems: 'center',
                            gap: '8px',
                            padding: '8px 12px',
                            background: '#f0fdf4',
                            color: '#15803d',
                            textDecoration: 'none',
                            borderRadius: '6px',
                            fontWeight: 600,
                            fontSize: '0.9rem'
                          }}
                        >
                          <ImageIcon size={16} /> Réponse
                        </a>
                      )}
                    </div>
                  </div>

                  {/* Commentaires étudiant */}
                  {sub.commentaires && (
                    <div style={{ marginBottom: '15px', padding: '12px', background: 'white', borderRadius: '6px', borderLeft: '3px solid #3b82f6' }}>
                      <div style={{ display: 'flex', alignItems: 'center', gap: '8px', marginBottom: '8px', fontWeight: 600, fontSize: '0.9rem' }}>
                        <MessageSquare size={16} /> Commentaire de l'étudiant
                      </div>
                      <p style={{ margin: 0, color: '#666', whiteSpace: 'pre-wrap' }}>{sub.commentaires}</p>
                    </div>
                  )}

                  {/* Formulaire correction */}
                  {sub.statut !== 'CORRIGE' && (
                    <div style={{ marginTop: '15px', padding: '15px', background: 'white', borderRadius: '8px', border: '1px solid #e5e7eb' }}>
                      <h4 style={{ margin: '0 0 12px 0', fontSize: '0.95rem', fontWeight: 700 }}>✏️ Correction</h4>

                      <div style={{ marginBottom: '12px' }}>
                        <label style={{ display: 'block', fontWeight: 600, marginBottom: '6px', fontSize: '0.9rem' }}>Note (sur 20)</label>
                        <input
                          type="number"
                          min="0"
                          max="20"
                          value={correctionData[sub.id]?.note || ''}
                          onChange={(e) => setCorrectionData({
                            ...correctionData,
                            [sub.id]: { ...correctionData[sub.id], note: parseInt(e.target.value) }
                          })}
                          style={{
                            width: '100px',
                            padding: '8px',
                            border: '1px solid #ddd',
                            borderRadius: '6px'
                          }}
                          placeholder="Ex: 15"
                        />
                      </div>

                      <div style={{ marginBottom: '12px' }}>
                        <label style={{ display: 'block', fontWeight: 600, marginBottom: '6px', fontSize: '0.9rem' }}>Retour de correction</label>
                        <textarea
                          value={correctionData[sub.id]?.retour || ''}
                          onChange={(e) => setCorrectionData({
                            ...correctionData,
                            [sub.id]: { ...correctionData[sub.id], retour: e.target.value }
                          })}
                          placeholder="Écrivez vos commentaires de correction..."
                          rows="4"
                          style={{
                            width: '100%',
                            padding: '10px',
                            border: '1px solid #ddd',
                            borderRadius: '6px',
                            boxSizing: 'border-box',
                            fontFamily: 'inherit'
                          }}
                        />
                      </div>

                      <div style={{ display: 'flex', gap: '10px', justifyContent: 'flex-end' }}>
                        {sub.statut === 'SOUMIS' && (
                          <button
                            onClick={() => handleMarquerEnCorrection(sub.id)}
                            style={{
                              padding: '8px 16px',
                              background: '#dbeafe',
                              color: '#1e40af',
                              border: 'none',
                              borderRadius: '6px',
                              cursor: 'pointer',
                              fontWeight: 600,
                              fontSize: '0.9rem'
                            }}
                          >
                            ⏳ En correction
                          </button>
                        )}
                        <button
                          onClick={() => handleTerminerCorrection(sub.id)}
                          style={{
                            padding: '8px 16px',
                            background: '#10b981',
                            color: 'white',
                            border: 'none',
                            borderRadius: '6px',
                            cursor: 'pointer',
                            fontWeight: 600,
                            fontSize: '0.9rem'
                          }}
                        >
                          ✅ Terminer la correction
                        </button>
                      </div>
                    </div>
                  )}

                  {/* Correction terminée */}
                  {sub.statut === 'CORRIGE' && (
                    <div style={{ padding: '12px', background: '#f0fdf4', border: '1px solid #86efac', borderRadius: '6px' }}>
                      <div style={{ display: 'flex', alignItems: 'center', gap: '8px', marginBottom: '8px', color: '#15803d', fontWeight: 700 }}>
                        <CheckCircle size={18} /> Corrigé
                      </div>
                      <p style={{ margin: '0', fontSize: '0.9rem' }}>
                        <strong>Note:</strong> {sub.noteObtenue}/20
                      </p>
                      {sub.retourCorrection && (
                        <p style={{ margin: '8px 0 0 0', color: '#666', whiteSpace: 'pre-wrap' }}>
                          {sub.retourCorrection}
                        </p>
                      )}
                    </div>
                  )}
                </div>
              )}
            </div>
          ))}
        </div>
      )}

      <style jsx>{`
        .spinner {
          animation: spin 1s linear infinite;
        }
        @keyframes spin {
          from { transform: rotate(0deg); }
          to { transform: rotate(360deg); }
        }
      `}</style>
    </div>
  );
};

export default SubmissionsList;
