import React, { useState, useEffect } from 'react';
import { AlertCircle, Loader, Download, Eye, Check, Star, FileText, Filter, Search, Printer } from 'lucide-react';
import { travauxAPI } from '../services/api';

/**
 * TravailEtudiantManager - Interface pour les profs de gérer les travaux d'étudiants
 * Télécharger, évaluer, imprimer
 */
const TravailEtudiantManager = ({ professeurId, matiereId }) => {
  const [travaux, setTravaux] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [filterStatut, setFilterStatut] = useState('SOUMIS');
  const [filterFormat, setFilterFormat] = useState('all');
  const [searchTerm, setSearchTerm] = useState('');
  const [expandedId, setExpandedId] = useState(null);
  const [evaluationData, setEvaluationData] = useState({});

  useEffect(() => {
    loadTravaux();
  }, [matiereId]);

  const loadTravaux = async () => {
    try {
      setLoading(true);
      const res = matiereId
        ? await travauxAPI.getTravailsMatiereEnAttente(matiereId)
        : await travauxAPI.getTravailsEnAttente(professeurId);
      setTravaux(res.data || []);
    } catch (err) {
      setError('Erreur lors du chargement des travaux');
    } finally {
      setLoading(false);
    }
  };

  const handleMarquerEnEvaluation = async (travailId) => {
    try {
      await travauxAPI.marquerEnEvaluation(travailId);
      await loadTravaux();
    } catch (err) {
      setError('Erreur lors de la mise à jour');
    }
  };

  const handleEvaluer = async (travailId) => {
    const data = evaluationData[travailId];
    if (!data || data.note === undefined || data.note === '') {
      setError('La note est requise');
      return;
    }

    try {
      await travauxAPI.evaluerTravail(travailId, parseInt(data.note), data.commentaires);
      await loadTravaux();
      setEvaluationData({ ...evaluationData, [travailId]: null });
      setExpandedId(null);
    } catch (err) {
      setError('Erreur lors de l\'évaluation');
    }
  };

  const handlePrint = (travail) => {
    const printWindow = window.open('', '', 'height=600,width=800');
    printWindow.document.write(`
      <html>
        <head>
          <title>Travail - ${travail.titre}</title>
          <style>
            body { font-family: Arial, sans-serif; margin: 20px; }
            .header { border-bottom: 2px solid #333; margin-bottom: 20px; padding-bottom: 10px; }
            h1 { margin: 0 0 5px 0; }
            .meta { color: #666; font-size: 0.9em; }
            .info { background: #f0f0f0; padding: 15px; border-radius: 5px; margin: 20px 0; }
            .info div { margin: 5px 0; }
            .note { color: green; font-weight: bold; font-size: 1.2em; }
            .commentaires { background: white; padding: 15px; border: 1px solid #ddd; margin: 20px 0; }
          </style>
        </head>
        <body>
          <div class="header">
            <h1>${travail.titre}</h1>
            <div class="meta">
              Étudiant: ${travail.etudiant?.nomComplet} |
              Matière: ${travail.matiere?.nom} |
              Date: ${new Date(travail.dateUpload).toLocaleDateString('fr-FR')}
            </div>
          </div>

          <div class="info">
            <div><strong>Format:</strong> ${travail.format}</div>
            <div><strong>Statut:</strong> ${travail.statut}</div>
            <div><strong>Lien fichier:</strong> <a href="${travail.fichierUrl}" target="_blank">${travail.fichierUrl}</a></div>
          </div>

          ${travail.noteObtenue !== null ? `
            <div class="info">
              <div class="note">Note: ${travail.noteObtenue}/20</div>
              <div style="margin-top: 10px; color: #666;">${travail.commentairesEvaluation}</div>
            </div>
          ` : ''}

          <p style="text-align: center; color: #999; margin-top: 40px; font-size: 0.85em;">
            Généré depuis UL Smart Campus - ${new Date().toLocaleString('fr-FR')}
          </p>
        </body>
      </html>
    `);
    printWindow.document.close();
    printWindow.print();
  };

  // Filtrer
  const filtered = travaux.filter(t => {
    const matchStatut = filterStatut === 'all' || t.statut === filterStatut;
    const matchFormat = filterFormat === 'all' || t.format === filterFormat;
    const matchSearch = t.titre.toLowerCase().includes(searchTerm.toLowerCase()) ||
                       t.etudiant?.nomComplet?.toLowerCase().includes(searchTerm.toLowerCase());
    return matchStatut && matchFormat && matchSearch;
  });

  if (loading) return <div style={{ padding: '20px', textAlign: 'center' }}><Loader className="spinner" /> Chargement...</div>;

  const statuts = ['SOUMIS', 'EN_EVALUATION', 'EVALUE'];
  const formats = ['PDF', 'DOCX', 'XLSX', 'PPTX', 'JPEG', 'PNG', 'AUTRE'];

  return (
    <div style={{ padding: '20px' }}>
      <div style={{ marginBottom: '20px' }}>
        <h3 style={{ margin: '0 0 10px 0', fontSize: '1.2rem', fontWeight: 700 }}>📚 Travaux des Étudiants</h3>
        <p style={{ margin: 0, color: '#666', fontSize: '0.9rem' }}>
          Gérer, évaluer et télécharger les travaux de vos étudiants
        </p>
      </div>

      {error && (
        <div style={{ background: '#fee', padding: '12px 15px', borderRadius: '8px', marginBottom: '15px', color: '#c33', display: 'flex', gap: '10px' }}>
          <AlertCircle size={18} />
          {error}
        </div>
      )}

      {/* Filtres */}
      <div style={{ display: 'flex', gap: '10px', marginBottom: '20px', flexWrap: 'wrap', alignItems: 'center' }}>
        {/* Recherche */}
        <div style={{ flex: 1, minWidth: '200px', display: 'flex', alignItems: 'center', gap: '8px', background: 'white', padding: '8px 12px', borderRadius: '6px', border: '1px solid #ddd' }}>
          <Search size={16} style={{ color: '#999' }} />
          <input
            type="text"
            placeholder="Rechercher par titre ou étudiant..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            style={{ border: 'none', outline: 'none', flex: 1, background: 'transparent' }}
          />
        </div>

        {/* Filtre Statut */}
        <select
          value={filterStatut}
          onChange={(e) => setFilterStatut(e.target.value)}
          style={{ padding: '8px 12px', border: '1px solid #ddd', borderRadius: '6px', background: 'white', cursor: 'pointer' }}
        >
          <option value="all">Tous les statuts</option>
          {statuts.map(s => (
            <option key={s} value={s}>
              {s === 'SOUMIS' ? '📥 Soumis' : s === 'EN_EVALUATION' ? '⏳ En évaluation' : '✅ Évalué'}
            </option>
          ))}
        </select>

        {/* Filtre Format */}
        <select
          value={filterFormat}
          onChange={(e) => setFilterFormat(e.target.value)}
          style={{ padding: '8px 12px', border: '1px solid #ddd', borderRadius: '6px', background: 'white', cursor: 'pointer' }}
        >
          <option value="all">Tous les formats</option>
          {formats.map(f => (
            <option key={f} value={f}>{f}</option>
          ))}
        </select>
      </div>

      {/* Liste travaux */}
      {filtered.length === 0 ? (
        <div style={{ padding: '40px 20px', textAlign: 'center', color: '#999', background: '#f8f9fa', borderRadius: '8px' }}>
          <FileText size={40} style={{ margin: '0 auto 15px', display: 'block', opacity: 0.5 }} />
          <p style={{ margin: 0, fontWeight: 600 }}>Aucun travail pour ce filtre</p>
        </div>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
          {filtered.map(travail => (
            <div
              key={travail.id}
              style={{
                background: 'white',
                border: '1px solid #e5e7eb',
                borderRadius: '10px',
                overflow: 'hidden'
              }}
            >
              {/* En-tête */}
              <div
                onClick={() => setExpandedId(expandedId === travail.id ? null : travail.id)}
                style={{
                  padding: '15px',
                  display: 'flex',
                  justifyContent: 'space-between',
                  alignItems: 'center',
                  cursor: 'pointer',
                  background: expandedId === travail.id ? '#f9fafb' : 'white',
                  borderBottom: expandedId === travail.id ? '1px solid #e5e7eb' : 'none'
                }}
                onMouseEnter={(e) => e.currentTarget.style.background = '#f9fafb'}
                onMouseLeave={(e) => e.currentTarget.style.background = expandedId === travail.id ? '#f9fafb' : 'white'}
              >
                <div style={{ flex: 1 }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '12px', marginBottom: '8px' }}>
                    <strong style={{ fontSize: '1rem' }}>{travail.titre}</strong>
                    <span style={{
                      background: travail.statut === 'EVALUE' ? '#f0fdf4' : travail.statut === 'EN_EVALUATION' ? '#dbeafe' : '#fef3c7',
                      color: travail.statut === 'EVALUE' ? '#15803d' : travail.statut === 'EN_EVALUATION' ? '#1e40af' : '#92400e',
                      padding: '4px 10px',
                      borderRadius: '4px',
                      fontSize: '0.8rem',
                      fontWeight: 700
                    }}>
                      {travail.statut === 'EVALUE' ? '✅ Évalué' : travail.statut === 'EN_EVALUATION' ? '⏳ En évaluation' : '📥 Soumis'}
                    </span>
                  </div>
                  <p style={{ margin: '0', color: '#666', fontSize: '0.9rem' }}>
                    {travail.etudiant?.nomComplet} • {travail.matiere?.nom} • {new Date(travail.dateUpload).toLocaleDateString('fr-FR')}
                  </p>
                </div>
                <div style={{ fontSize: '0.85rem', fontWeight: 600, color: '#3b82f6' }}>
                  {expandedId === travail.id ? '▼' : '▶'}
                </div>
              </div>

              {/* Détails */}
              {expandedId === travail.id && (
                <div style={{ padding: '15px', background: '#f9fafb', borderTop: '1px solid #e5e7eb' }}>
                  {/* Infos fichier */}
                  <div style={{ marginBottom: '15px', padding: '12px', background: 'white', borderRadius: '6px' }}>
                    <div style={{ display: 'flex', gap: '10px', alignItems: 'center', marginBottom: '8px' }}>
                      <span style={{ fontSize: '1.2rem' }}>📄</span>
                      <strong style={{ fontSize: '0.95rem' }}>Format: {travail.format}</strong>
                    </div>
                    {travail.description && (
                      <p style={{ margin: '0', color: '#666', fontSize: '0.9rem' }}>{travail.description}</p>
                    )}
                  </div>

                  {/* Boutons d'action */}
                  <div style={{ display: 'flex', gap: '8px', marginBottom: '15px', flexWrap: 'wrap' }}>
                    {travail.fichierUrl && (
                      <a
                        href={travail.fichierUrl}
                        target="_blank"
                        rel="noreferrer"
                        download
                        style={{
                          display: 'flex',
                          alignItems: 'center',
                          gap: '6px',
                          padding: '8px 12px',
                          background: '#3b82f6',
                          color: 'white',
                          textDecoration: 'none',
                          borderRadius: '6px',
                          fontSize: '0.9rem',
                          fontWeight: 600,
                          cursor: 'pointer'
                        }}
                      >
                        <Download size={14} /> Télécharger
                      </a>
                    )}
                    <button
                      onClick={() => handlePrint(travail)}
                      style={{
                        display: 'flex',
                        alignItems: 'center',
                        gap: '6px',
                        padding: '8px 12px',
                        background: '#10b981',
                        color: 'white',
                        border: 'none',
                        borderRadius: '6px',
                        fontSize: '0.9rem',
                        fontWeight: 600,
                        cursor: 'pointer'
                      }}
                    >
                      <Printer size={14} /> Imprimer
                    </button>
                  </div>

                  {/* Formulaire évaluation */}
                  {travail.statut !== 'EVALUE' && (
                    <div style={{ padding: '15px', background: 'white', borderRadius: '8px', border: '1px solid #e5e7eb' }}>
                      <h4 style={{ margin: '0 0 12px 0', fontSize: '0.95rem', fontWeight: 700 }}>✏️ Évaluation</h4>

                      <div style={{ marginBottom: '12px' }}>
                        <label style={{ display: 'block', fontWeight: 600, marginBottom: '6px', fontSize: '0.9rem' }}>
                          Note (sur 20) *
                        </label>
                        <input
                          type="number"
                          min="0"
                          max="20"
                          value={evaluationData[travail.id]?.note || ''}
                          onChange={(e) => setEvaluationData({
                            ...evaluationData,
                            [travail.id]: { ...evaluationData[travail.id], note: e.target.value }
                          })}
                          style={{
                            width: '100px',
                            padding: '8px',
                            border: '1px solid #ddd',
                            borderRadius: '6px'
                          }}
                          placeholder="0-20"
                        />
                      </div>

                      <div style={{ marginBottom: '12px' }}>
                        <label style={{ display: 'block', fontWeight: 600, marginBottom: '6px', fontSize: '0.9rem' }}>
                          Commentaires
                        </label>
                        <textarea
                          value={evaluationData[travail.id]?.commentaires || ''}
                          onChange={(e) => setEvaluationData({
                            ...evaluationData,
                            [travail.id]: { ...evaluationData[travail.id], commentaires: e.target.value }
                          })}
                          placeholder="Écrivez votre retour..."
                          rows="3"
                          style={{
                            width: '100%',
                            padding: '10px',
                            border: '1px solid #ddd',
                            borderRadius: '6px',
                            boxSizing: 'border-box',
                            fontFamily: 'inherit'
                          }}
                        />
                      </div>

                      <div style={{ display: 'flex', gap: '10px', justifyContent: 'flex-end' }}>
                        {travail.statut === 'SOUMIS' && (
                          <button
                            onClick={() => handleMarquerEnEvaluation(travail.id)}
                            style={{
                              padding: '8px 16px',
                              background: '#dbeafe',
                              color: '#1e40af',
                              border: 'none',
                              borderRadius: '6px',
                              cursor: 'pointer',
                              fontWeight: 600,
                              fontSize: '0.9rem'
                            }}
                          >
                            ⏳ En évaluation
                          </button>
                        )}
                        <button
                          onClick={() => handleEvaluer(travail.id)}
                          style={{
                            padding: '8px 16px',
                            background: '#10b981',
                            color: 'white',
                            border: 'none',
                            borderRadius: '6px',
                            cursor: 'pointer',
                            fontWeight: 600,
                            fontSize: '0.9rem'
                          }}
                        >
                          ✅ Valider l'évaluation
                        </button>
                      </div>
                    </div>
                  )}

                  {/* Évaluation terminée */}
                  {travail.statut === 'EVALUE' && (
                    <div style={{ padding: '12px', background: '#f0fdf4', border: '1px solid #86efac', borderRadius: '6px' }}>
                      <div style={{ display: 'flex', alignItems: 'center', gap: '8px', marginBottom: '8px', color: '#15803d', fontWeight: 700 }}>
                        <Check size={18} /> Évaluation terminée
                      </div>
                      <p style={{ margin: '0 0 8px 0', fontSize: '0.95rem' }}>
                        <strong>Note:</strong> {travail.noteObtenue}/20
                      </p>
                      {travail.commentairesEvaluation && (
                        <p style={{ margin: '0', color: '#666', whiteSpace: 'pre-wrap', fontSize: '0.9rem' }}>
                          {travail.commentairesEvaluation}
                        </p>
                      )}
                    </div>
                  )}
                </div>
              )}
            </div>
          ))}
        </div>
      )}

      <style jsx>{`
        .spinner {
          animation: spin 1s linear infinite;
        }
        @keyframes spin {
          from { transform: rotate(0deg); }
          to { transform: rotate(360deg); }
        }
      `}</style>
    </div>
  );
};

export default TravailEtudiantManager;
