import React from 'react';
import { motion } from 'framer-motion';
import { Menu, Bell, LogOut, User, Settings } from 'lucide-react';
import RevisiaLogo from './RevisiaLogo';
import '../styles/header.css';

/**
 * Header Principal avec Logo REVISIA-H24
 * Utilisé dans TOUS les dashboards
 */
const Header = ({
  user,
  onMenuClick,
  onLogout,
  title = '',
  showNotifications = true
}) => {
  return (
    <motion.header
      className="revisia-header"
      initial={{ y: -60, opacity: 0 }}
      animate={{ y: 0, opacity: 1 }}
      transition={{ duration: 0.5 }}
    >
      {/* Barre de marque REVISIA-H24 */}
      <div className="header-brand-bar">
        <div className="brand-logo-container">
          <RevisiaLogo size="small" variant="icon" />
          <div className="brand-text">
            <div className="brand-name">REVISIA</div>
            <div className="brand-h24">H24</div>
          </div>
        </div>
      </div>

      {/* Contenu du header */}
      <div className="header-content">
        {/* Gauche: Menu + Title */}
        <div className="header-left">
          <button
            className="menu-btn"
            onClick={onMenuClick}
            title="Menu"
          >
            <Menu size={24} />
          </button>
          {title && <h1 className="header-title">{title}</h1>}
        </div>

        {/* Droite: Actions utilisateur */}
        <div className="header-right">
          {/* Notifications */}
          {showNotifications && (
            <motion.button
              className="header-action-btn notifications-btn"
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
              title="Notifications"
            >
              <Bell size={20} />
              <span className="notification-badge">3</span>
            </motion.button>
          )}

          {/* Profil utilisateur */}
          <motion.div
            className="user-profile"
            whileHover={{ scale: 1.02 }}
          >
            <div className="user-avatar">
              {user?.photoUrl ? (
                <img src={user.photoUrl} alt={user.nomComplet} />
              ) : (
                <span>{user?.nomComplet?.charAt(0).toUpperCase() || 'U'}</span>
              )}
            </div>
            <div className="user-info">
              <p className="user-name">{user?.nomComplet || 'Utilisateur'}</p>
              <p className="user-role">{user?.role || 'Rôle'}</p>
            </div>
          </motion.div>

          {/* Menu actions */}
          <div className="header-actions">
            <motion.button
              className="action-icon"
              whileHover={{ scale: 1.1 }}
              whileTap={{ scale: 0.9 }}
              title="Paramètres"
            >
              <Settings size={18} />
            </motion.button>
            <motion.button
              className="action-icon logout"
              whileHover={{ scale: 1.1 }}
              whileTap={{ scale: 0.9 }}
              onClick={onLogout}
              title="Déconnexion"
            >
              <LogOut size={18} />
            </motion.button>
          </div>
        </div>
      </div>

      {/* Ligne de séparation */}
      <div className="header-divider"></div>
    </motion.header>
  );
};

export default Header;
