import React, { useState } from 'react';
import { useToast } from '../../hooks/useToast';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Plus, Edit2, Trash2, FileText, Search, X,
  Loader, ChevronDown, ChevronUp, BookOpen
} from 'lucide-react';
import { professeurAPI } from '../../services/api';

const NIVEAUX = ['L1', 'L2', 'L3', 'M1', 'M2', 'D1', 'D2', 'D3'];

/**
 * VueFichesEnseignement — Gestion complète des fiches d'enseignement
 * CRUD complet : créer, afficher, modifier, supprimer
 */
const VueFichesEnseignement = ({ user, fiches = [], matieres = [], onRefresh }) => {
  const { showToast, ToastUI } = useToast();
  const [searchTerm, setSearchTerm]     = useState('');
  const [filterNiveau, setFilterNiveau] = useState('');
  const [showModal, setShowModal]       = useState(false);
  const [editingFiche, setEditingFiche] = useState(null);
  const [loading, setLoading]           = useState(false);
  const [expandedId, setExpandedId]     = useState(null);

  const [form, setForm] = useState({
    titre:     '',
    contenu:   '',
    objectifs: '',
    prerequis: '',
    matiereId: '',
    niveau:    '',
  });

  // ── Filtrage ──────────────────────────────────────────────
  const filtered = fiches.filter(f => {
    const matchSearch = f.titre?.toLowerCase().includes(searchTerm.toLowerCase());
    const matchNiveau = !filterNiveau || f.niveau === filterNiveau;
    return matchSearch && matchNiveau;
  });

  // ── Ouvrir modal ──────────────────────────────────────────
  const openCreate = () => {
    setEditingFiche(null);
    setForm({ titre: '', contenu: '', objectifs: '', prerequis: '', matiereId: '', niveau: '' });
    setShowModal(true);
  };

  const openEdit = (fiche) => {
    setEditingFiche(fiche);
    setForm({
      titre:     fiche.titre || '',
      contenu:   fiche.contenu || '',
      objectifs: fiche.objectifs || '',
      prerequis: fiche.prerequis || '',
      matiereId: fiche.matiere?.id || '',
      niveau:    fiche.niveau || '',
    });
    setShowModal(true);
  };

  // ── Sauvegarder ────────────────────────────────────────────
  const handleSave = async () => {
    if (!form.titre.trim())     return showToast('Le titre est requis', 'error');
    if (!form.contenu.trim())   return showToast('Le contenu est requis', 'error');
    if (!form.matiereId)        return showToast('La matière est requise', 'error');
    if (!form.niveau)           return showToast('Le niveau est requis', 'error');

    try {
      setLoading(true);
      if (editingFiche) {
        await professeurAPI.updateFiche(editingFiche.id, { ...form, matiereId: Number(form.matiereId) });
        showToast('Fiche mise à jour !');
      } else {
        await professeurAPI.createFiche(user.id, { ...form, matiereId: Number(form.matiereId) });
        showToast('Fiche créée avec succès !');
      }
      setShowModal(false);
      onRefresh?.();
    } catch (err) {
      console.error(err);
      showToast('Erreur lors de la sauvegarde', 'error');
    } finally {
      setLoading(false);
    }
  };

  // ── Supprimer ──────────────────────────────────────────────
  const handleDelete = async (ficheId, titre) => {
    if (!window.confirm(`Supprimer la fiche "${titre}" ?`)) return;
    try {
      setLoading(true);
      await professeurAPI.deleteFiche(ficheId);
      showToast('Fiche supprimée');
      onRefresh?.();
    } catch (err) {
      showToast('Erreur lors de la suppression', 'error');
    } finally {
      setLoading(false);
    }
  };

  const toggleExpand = (id) => setExpandedId(prev => prev === id ? null : id);

  return (
    <motion.div
      className="vue-fiches"
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
    >
      {ToastUI}

      {/* ── Header ── */}
      <div className="vue-header">
        <h2>Fiches d'Enseignement</h2>
        <button className="btn-primary" onClick={openCreate} disabled={loading}>
          <Plus size={18} /> Nouvelle Fiche
        </button>
      </div>

      {/* ── Barre de filtres ── */}
      <motion.div className="filters-bar" initial={{ opacity: 0, y: -8 }} animate={{ opacity: 1, y: 0 }}>
        <div className="search-input">
          <Search size={16} />
          <input
            type="text"
            placeholder="Rechercher une fiche..."
            value={searchTerm}
            onChange={e => setSearchTerm(e.target.value)}
          />
        </div>
        <select
          className="filter-select"
          value={filterNiveau}
          onChange={e => setFilterNiveau(e.target.value)}
        >
          <option value="">Tous les niveaux</option>
          {NIVEAUX.map(n => <option key={n} value={n}>{n}</option>)}
        </select>
      </motion.div>

      {/* ── Liste des fiches ── */}
      {filtered.length === 0 ? (
        <div className="empty-state">
          <FileText size={48} />
          <p>{searchTerm ? 'Aucune fiche correspondante' : 'Aucune fiche créée'}</p>
          {!searchTerm && (
            <button className="btn-secondary" onClick={openCreate}>
              Créer votre première fiche
            </button>
          )}
        </div>
      ) : (
        <div className="fiches-grid">
          {filtered.map((fiche, idx) => (
            <motion.div
              key={fiche.id}
              className="fiche-card"
              initial={{ opacity: 0, y: 12 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: idx * 0.05 }}
            >
              {/* En-tête de la carte */}
              <div className="fiche-card-header" onClick={() => toggleExpand(fiche.id)}>
                <div className="fiche-meta">
                  <BookOpen size={16} className="fiche-icon" />
                  <div>
                    <h3 className="fiche-titre">{fiche.titre}</h3>
                    <span className="fiche-info">
                      {fiche.matiere?.nom || '—'} · Niveau {fiche.niveau || '—'}
                    </span>
                  </div>
                </div>
                <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                  <button
                    className="btn-icon"
                    onClick={e => { e.stopPropagation(); openEdit(fiche); }}
                    title="Modifier"
                  >
                    <Edit2 size={16} />
                  </button>
                  <button
                    className="btn-icon danger"
                    onClick={e => { e.stopPropagation(); handleDelete(fiche.id, fiche.titre); }}
                    title="Supprimer"
                  >
                    <Trash2 size={16} />
                  </button>
                  {expandedId === fiche.id ? <ChevronUp size={16} /> : <ChevronDown size={16} />}
                </div>
              </div>

              {/* Contenu déroulant */}
              <AnimatePresence>
                {expandedId === fiche.id && (
                  <motion.div
                    className="fiche-card-body"
                    initial={{ height: 0, opacity: 0 }}
                    animate={{ height: 'auto', opacity: 1 }}
                    exit={{ height: 0, opacity: 0 }}
                    transition={{ duration: 0.25 }}
                  >
                    {fiche.objectifs && (
                      <div className="fiche-section">
                        <strong>🎯 Objectifs</strong>
                        <p>{fiche.objectifs}</p>
                      </div>
                    )}
                    {fiche.prerequis && (
                      <div className="fiche-section">
                        <strong>📌 Prérequis</strong>
                        <p>{fiche.prerequis}</p>
                      </div>
                    )}
                    <div className="fiche-section">
                      <strong>📝 Contenu</strong>
                      <pre className="fiche-contenu">{fiche.contenu}</pre>
                    </div>
                    <div className="fiche-dates">
                      Créé le {fiche.dateCreation
                        ? new Date(fiche.dateCreation).toLocaleDateString('fr-FR')
                        : '—'}
                    </div>
                  </motion.div>
                )}
              </AnimatePresence>
            </motion.div>
          ))}
        </div>
      )}

      {/* ── Modal Créer / Éditer ── */}
      <AnimatePresence>
        {showModal && (
          <FicheModal
            isEditing={!!editingFiche}
            form={form}
            setForm={setForm}
            matieres={matieres}
            loading={loading}
            onSave={handleSave}
            onClose={() => setShowModal(false)}
          />
        )}
      </AnimatePresence>
    </motion.div>
  );
};

/* ════════════════════════════════════════════════════════════
   MODAL FICHE
════════════════════════════════════════════════════════════ */
const FicheModal = ({ isEditing, form, setForm, matieres, loading, onSave, onClose }) => {
  const handleChange = e => {
    const { name, value } = e.target;
    setForm(prev => ({ ...prev, [name]: value }));
  };

  return (
    <motion.div
      className="modal-overlay"
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      onClick={onClose}
    >
      <motion.div
        className="modal-content modal-large"
        onClick={e => e.stopPropagation()}
        initial={{ scale: 0.9, opacity: 0, y: 20 }}
        animate={{ scale: 1, opacity: 1, y: 0 }}
        exit={{ scale: 0.9, opacity: 0, y: 20 }}
      >
        {/* Header modal */}
        <div className="modal-header">
          <h3>{isEditing ? '✏️ Modifier la fiche' : '📄 Nouvelle fiche d\'enseignement'}</h3>
          <button className="btn-icon" onClick={onClose}><X size={20} /></button>
        </div>

        <div className="modal-body-scroll">
          {/* Titre */}
          <div className="form-group">
            <label>Titre <span className="required">*</span></label>
            <input
              type="text"
              name="titre"
              value={form.titre}
              onChange={handleChange}
              placeholder="Ex: Introduction aux algorithmes de tri"
              maxLength={200}
            />
          </div>

          {/* Matière + Niveau sur la même ligne */}
          <div className="form-row">
            <div className="form-group">
              <label>Matière <span className="required">*</span></label>
              <select name="matiereId" value={form.matiereId} onChange={handleChange}>
                <option value="">— Sélectionner —</option>
                {matieres.map(m => (
                  <option key={m.id} value={m.id}>{m.nom}</option>
                ))}
              </select>
            </div>
            <div className="form-group">
              <label>Niveau <span className="required">*</span></label>
              <select name="niveau" value={form.niveau} onChange={handleChange}>
                <option value="">— Sélectionner —</option>
                {NIVEAUX.map(n => <option key={n} value={n}>{n}</option>)}
              </select>
            </div>
          </div>

          {/* Objectifs */}
          <div className="form-group">
            <label>🎯 Objectifs pédagogiques</label>
            <textarea
              name="objectifs"
              value={form.objectifs}
              onChange={handleChange}
              placeholder="À l'issue de ce cours, l'étudiant sera capable de..."
              rows={3}
            />
          </div>

          {/* Prérequis */}
          <div className="form-group">
            <label>📌 Prérequis</label>
            <textarea
              name="prerequis"
              value={form.prerequis}
              onChange={handleChange}
              placeholder="Connaissances requises avant ce cours..."
              rows={2}
            />
          </div>

          {/* Contenu */}
          <div className="form-group">
            <label>📝 Contenu de la fiche <span className="required">*</span></label>
            <textarea
              name="contenu"
              value={form.contenu}
              onChange={handleChange}
              placeholder="Rédigez le contenu de votre fiche d'enseignement ici (Markdown supporté)..."
              rows={8}
              style={{ fontFamily: 'monospace', fontSize: '0.85rem' }}
            />
            <small style={{ color: '#475569', fontSize: '0.72rem' }}>
              Supporte le Markdown : **gras**, *italique*, # Titre, - liste
            </small>
          </div>
        </div>

        {/* Actions */}
        <div className="modal-actions">
          <button className="btn-secondary" onClick={onClose} disabled={loading}>
            Annuler
          </button>
          <button className="btn-primary" onClick={onSave} disabled={loading}>
            {loading ? <Loader className="spinner" size={18} /> : null}
            {loading ? 'Enregistrement…' : (isEditing ? 'Mettre à jour' : 'Créer la fiche')}
          </button>
        </div>
      </motion.div>
    </motion.div>
  );
};

export default VueFichesEnseignement;
