import React from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { X } from 'lucide-react';
import RevisiaLogo from './RevisiaLogo';
import '../styles/sidebar.css';

/**
 * Sidebar REVISIA H24 — Bleu ciel + Orange
 * Responsive APK / Mobile / Desktop
 */
const Sidebar = ({ isOpen, onClose, menuItems = [], activeItem = null, user = null }) => {
  const initiale = user?.nomComplet?.charAt(0).toUpperCase() || 'U';
  const roleLabel = {
    SUPER_ADMIN: 'Super Admin',
    ADMIN: 'Administrateur',
    ENSEIGNANT: 'Enseignant',
    ETUDIANT: 'Étudiant',
    PARENT: 'Parent',
    COMMERCIAL: 'Commercial',
    DELEGUE: 'Délégué',
  }[user?.role] || user?.role || '';

  return (
    <AnimatePresence>
      {isOpen && (
        <>
          {/* Overlay avec backdrop blur */}
          <motion.div
            className="sidebar-overlay"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={onClose}
          />

          {/* Sidebar */}
          <motion.aside
            className="revisia-sidebar"
            initial={{ x: '-100%', opacity: 0 }}
            animate={{ x: 0, opacity: 1 }}
            exit={{ x: '-100%', opacity: 0 }}
            transition={{ type: 'spring', stiffness: 380, damping: 34 }}
          >
            {/* Header dégradé bleu ciel → orange */}
            <div className="sidebar-header">
              <div className="sidebar-logo" onClick={onClose}>
                <RevisiaLogo size="small" variant="icon" />
                <div>
                  <div className="sidebar-brand-text">
                    <span className="sidebar-brand-revisia">REVISIA</span>
                    <span className="sidebar-brand-h24">H24</span>
                  </div>
                  <p className="sidebar-tagline">Plateforme Académique</p>
                </div>
              </div>

              <button
                className="sidebar-close"
                onClick={onClose}
                title="Fermer"
                aria-label="Fermer le menu"
              >
                <X size={20} />
              </button>
            </div>

            {/* Carte utilisateur (si connecté) */}
            {user && (
              <div className="sidebar-user-card">
                <div className="sidebar-user-avatar">
                  {user.photoUrl
                    ? <img src={user.photoUrl} alt={user.nomComplet} style={{ width: '100%', height: '100%', objectFit: 'cover', borderRadius: '50%' }} />
                    : initiale
                  }
                </div>
                <div>
                  <p className="sidebar-user-name">{user.nomComplet || 'Utilisateur'}</p>
                  {roleLabel && <p className="sidebar-user-role">{roleLabel}</p>}
                </div>
              </div>
            )}

            {/* Menu */}
            <nav className="sidebar-menu" role="menu">
              {menuItems.map((item, index) => (
                <motion.a
                  key={index}
                  href={item.href || '#'}
                  role="menuitem"
                  className={`menu-item ${activeItem === item.key ? 'active' : ''}`}
                  onClick={e => {
                    e.preventDefault();
                    if (item.onClick) item.onClick();
                  }}
                  whileTap={{ scale: 0.97 }}
                >
                  <span className="menu-icon" aria-hidden="true">{item.icon}</span>
                  <span className="menu-label">{item.label}</span>

                  {/* Badge count */}
                  {item.badge > 0 && (
                    <span className="menu-badge">{item.badge > 99 ? '99+' : item.badge}</span>
                  )}

                  {/* Indicateur page active */}
                  {activeItem === item.key && (
                    <motion.div
                      className="menu-indicator"
                      layoutId="sidebar-indicator"
                      transition={{ type: 'spring', stiffness: 500, damping: 30 }}
                    />
                  )}
                </motion.a>
              ))}
            </nav>

            {/* Footer version */}
            <div className="sidebar-footer">
              <div className="sidebar-version">
                <div className="version-badge">v1.2.0</div>
                <p>REVISIA H24</p>
              </div>
            </div>
          </motion.aside>
        </>
      )}
    </AnimatePresence>
  );
};

export default Sidebar;
