import React, { useState, useEffect } from 'react';
import { Plus, Trash2, Send, AlertCircle, Loader } from 'lucide-react';
import { courseworkAPI, academicAPI } from '../../services/api';

/**
 * VueCoursework - Gestion des devoirs/coursework envoyés aux étudiants
 * Les profs créent des devoirs qui consomment les points d'abonnement des étudiants
 */
const VueCoursework = ({ user }) => {
  const [courseworks, setCourseworks] = useState([]);
  const [matieres, setMatieres] = useState([]);
  const [filieres, setFilieres] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  const [formData, setFormData] = useState({
    titre: '',
    description: '',
    matiereId: '',
    filiereId: '',
    niveau: 'L1',
    niveau_difficulte: 3,
    pointsConsommes: 5,
    dateEcheance: ''
  });

  useEffect(() => {
    loadData();
  }, [user?.id]);

  const loadData = async () => {
    try {
      setLoading(true);
      const [cwRes, matRes, filRes] = await Promise.all([
        courseworkAPI.getMyCourseworks(user.id).catch(() => ({ data: [] })),
        academicAPI.getMatieres().catch(() => ({ data: [] })),
        academicAPI.getFilieres().catch(() => ({ data: [] }))
      ]);

      setCourseworks(cwRes.data || []);
      setMatieres(matRes.data || []);
      setFilieres(filRes.data || []);
    } catch (err) {
      setError('Erreur lors du chargement');
    } finally {
      setLoading(false);
    }
  };

  const handleCreateCoursework = async (e) => {
    e.preventDefault();
    if (!formData.titre || !formData.matiereId) {
      setError('Remplissez les champs requis');
      return;
    }

    try {
      setSubmitting(true);
      setError('');

      const res = await courseworkAPI.createCoursework({
        ...formData,
        matiereId: parseInt(formData.matiereId),
        filiereId: formData.filiereId ? parseInt(formData.filiereId) : null
      });

      setCourseworks([res.data, ...courseworks]);
      setFormData({
        titre: '',
        description: '',
        matiereId: '',
        filiereId: '',
        niveau: 'L1',
        niveau_difficulte: 3,
        pointsConsommes: 5,
        dateEcheance: ''
      });
      setShowForm(false);
      setSuccess('✅ Coursework créé! Maintenant, envoyez-le aux étudiants.');
      setTimeout(() => setSuccess(''), 3000);
    } catch (err) {
      setError('❌ Erreur lors de la création');
    } finally {
      setSubmitting(false);
    }
  };

  const handleDeleteCoursework = async (id) => {
    if (window.confirm('Supprimer ce coursework?')) {
      try {
        await courseworkAPI.deleteCoursework(id);
        setCourseworks(courseworks.filter(cw => cw.id !== id));
        setSuccess('✅ Coursework supprimé');
        setTimeout(() => setSuccess(''), 3000);
      } catch (err) {
        setError('❌ Erreur lors de la suppression');
      }
    }
  };

  if (loading) return <div className="view-container"><Loader className="spinner" /> Chargement...</div>;

  return (
    <div className="view-container">
      <div className="view-header">
        <h2>📚 Coursework - Devoirs Dynamiques</h2>
        <p className="subtitle">Créez des devoirs qui consomment les points des étudiants</p>
      </div>

      {error && <div className="alert alert-error"><AlertCircle size={16} /> {error}</div>}
      {success && <div className="alert alert-success">{success}</div>}

      {/* Bouton Créer */}
      <button
        onClick={() => setShowForm(!showForm)}
        className="btn-primary"
        style={{ marginBottom: '20px' }}
      >
        <Plus size={18} /> Créer un Coursework
      </button>

      {/* Formulaire Création */}
      {showForm && (
        <div className="card" style={{ marginBottom: '30px', padding: '20px' }}>
          <h3>📝 Nouveau Coursework</h3>
          <form onSubmit={handleCreateCoursework}>
            <div className="form-group">
              <label>Titre *</label>
              <input
                type="text"
                placeholder="Ex: Exercices sur les boucles"
                value={formData.titre}
                onChange={(e) => setFormData({ ...formData, titre: e.target.value })}
                required
              />
            </div>

            <div className="form-group">
              <label>Description</label>
              <textarea
                placeholder="Instructions pour les étudiants..."
                value={formData.description}
                onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                rows="4"
              />
            </div>

            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '15px' }}>
              <div className="form-group">
                <label>Matière *</label>
                <select
                  value={formData.matiereId}
                  onChange={(e) => setFormData({ ...formData, matiereId: e.target.value })}
                  required
                >
                  <option value="">Sélectionner...</option>
                  {matieres.map(m => (
                    <option key={m.id} value={m.id}>{m.nom}</option>
                  ))}
                </select>
              </div>

              <div className="form-group">
                <label>Filière (optionnel)</label>
                <select
                  value={formData.filiereId}
                  onChange={(e) => setFormData({ ...formData, filiereId: e.target.value })}
                >
                  <option value="">Tous</option>
                  {filieres.map(f => (
                    <option key={f.id} value={f.id}>{f.nom}</option>
                  ))}
                </select>
              </div>
            </div>

            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: '15px' }}>
              <div className="form-group">
                <label>Niveau</label>
                <select value={formData.niveau} onChange={(e) => setFormData({ ...formData, niveau: e.target.value })}>
                  <option value="L1">L1</option>
                  <option value="L2">L2</option>
                  <option value="L3">L3</option>
                  <option value="M1">M1</option>
                  <option value="M2">M2</option>
                </select>
              </div>

              <div className="form-group">
                <label>Difficulté (1-5)</label>
                <input
                  type="range"
                  min="1"
                  max="5"
                  value={formData.niveau_difficulte}
                  onChange={(e) => setFormData({ ...formData, niveau_difficulte: parseInt(e.target.value) })}
                />
                <span>{formData.niveau_difficulte}/5</span>
              </div>

              <div className="form-group">
                <label>Points à consommer</label>
                <input
                  type="number"
                  min="1"
                  max="50"
                  value={formData.pointsConsommes}
                  onChange={(e) => setFormData({ ...formData, pointsConsommes: parseInt(e.target.value) })}
                />
              </div>
            </div>

            <div className="form-group">
              <label>Échéance (optionnel)</label>
              <input
                type="datetime-local"
                value={formData.dateEcheance}
                onChange={(e) => setFormData({ ...formData, dateEcheance: e.target.value })}
              />
            </div>

            <div style={{ display: 'flex', gap: '10px', justifyContent: 'flex-end' }}>
              <button type="button" onClick={() => setShowForm(false)} className="btn-secondary">
                Annuler
              </button>
              <button type="submit" disabled={submitting} className="btn-primary">
                {submitting ? <Loader className="spinner" /> : <Plus size={18} />}
                Créer
              </button>
            </div>
          </form>
        </div>
      )}

      {/* Liste Courseworks */}
      <div className="card-grid">
        {courseworks.length === 0 ? (
          <div className="empty-state">
            <h4>📚 Aucun coursework créé</h4>
            <p>Cliquez sur "Créer un Coursework" pour commencer!</p>
          </div>
        ) : (
          courseworks.map(cw => (
            <div key={cw.id} className="card coursework-card">
              <div className="card-header">
                <h4>{cw.titre}</h4>
                <span className="difficulty-badge">⭐ {cw.niveau_difficulte}/5</span>
              </div>

              <p className="text-muted">{cw.description}</p>

              <div className="coursework-info">
                <div><strong>Matière:</strong> {cw.matiere?.nom}</div>
                <div><strong>Points:</strong> {cw.pointsConsommes}</div>
                <div><strong>Visés:</strong> {cw.nombreEtudiantsVises}</div>
                <div><strong>Complétés:</strong> {cw.nombreEtudiantsCompletes}</div>
              </div>

              <div className="card-actions">
                <button
                  className="btn-danger btn-sm"
                  onClick={() => handleDeleteCoursework(cw.id)}
                >
                  <Trash2 size={16} /> Supprimer
                </button>
                <button className="btn-success btn-sm">
                  <Send size={16} /> Envoyer aux étudiants
                </button>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

export default VueCoursework;
