import React, { useState } from 'react';
import { useToast } from '../../hooks/useToast';
import { motion } from 'framer-motion';
import { Plus, Edit2, Trash2, Share2, Search, Loader } from 'lucide-react';
import { professeurAPI } from '../../services/api';

/**
 * VueGestionCours - Gestion des cours du professeur
 */
const VueGestionCours = ({ user, cours = [], matieres = [], onRefresh }) => {
  const { showToast, ToastUI } = useToast();
  const [searchTerm, setSearchTerm] = useState('');
  const [filterMatiere, setFilterMatiere] = useState('');
  const [showModal, setShowModal] = useState(false);
  const [editingCourse, setEditingCourse] = useState(null);
  const [loading, setLoading] = useState(false);
  const [courseFormData, setCourseFormData] = useState({
    titre: '',
    matiereId: '',
    niveau: '',
    visibilite: 'PRIVE',
    session: 'HARMATTAN',
    fichierUrl: ''
  });

  // Filtrer les cours
  const filteredCours = cours.filter(c => {
    const matchesSearch = c.titre.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesMatiere = !filterMatiere || (c.matiere?.id === parseInt(filterMatiere));
    return matchesSearch && matchesMatiere;
  });

  const handleCreateCourse = () => {
    setEditingCourse(null);
    setCourseFormData({
      titre: '',
      matiereId: '',
      niveau: '',
      visibilite: 'PRIVE',
      session: 'HARMATTAN',
      fichierUrl: ''
    });
    setShowModal(true);
  };

  const handleEditCourse = (course) => {
    setEditingCourse(course);
    setCourseFormData({
      titre: course.titre,
      matiereId: course.matiere?.id || '',
      niveau: course.niveau || '',
      visibilite: course.visibilite || 'PRIVE',
      session: course.session || 'HARMATTAN',
      fichierUrl: course.fichierUrl || ''
    });
    setShowModal(true);
  };

  const handleDeleteCourse = async (courseId) => {
    if (window.confirm('Êtes-vous sûr de vouloir supprimer ce cours?')) {
      try {
        setLoading(true);
        await professeurAPI.deleteCours(courseId);
        onRefresh?.();
      } catch (error) {
        showToast('Erreur lors de la suppression du cours', 'error');
        console.error(error);
      } finally {
        setLoading(false);
      }
    }
  };

  const handleSaveCourse = async () => {
    try {
      setLoading(true);
      if (editingCourse) {
        await professeurAPI.updateCours(editingCourse.id, courseFormData);
      } else {
        await professeurAPI.createCours(user.id, courseFormData);
      }
      setShowModal(false);
      onRefresh?.();
    } catch (error) {
      showToast('Erreur lors de la sauvegarde du cours', 'error');
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  const handleFormChange = (e) => {
    const { name, value } = e.target;
    setCourseFormData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  return (
    <motion.div
      className="vue-gestion-cours"
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
    >
      {ToastUI}
      <div className="vue-header">
        <h2>Mes Cours</h2>
        <button className="btn-primary" onClick={handleCreateCourse}>
          <Plus size={20} /> Ajouter un Cours
        </button>
      </div>

      {/* Filtres */}
      <motion.div
        className="filters-bar"
        initial={{ opacity: 0, y: -10 }}
        animate={{ opacity: 1, y: 0 }}
      >
        <div className="search-input">
          <Search size={18} />
          <input
            type="text"
            placeholder="Chercher un cours..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
        <select
          value={filterMatiere}
          onChange={(e) => setFilterMatiere(e.target.value)}
          className="filter-select"
        >
          <option value="">Toutes les matières</option>
          {matieres.map(m => (
            <option key={m.id} value={m.id}>{m.nom}</option>
          ))}
        </select>
      </motion.div>

      {/* Table de cours */}
      <motion.div
        className="courses-table-container"
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ delay: 0.2 }}
      >
        {filteredCours.length === 0 ? (
          <div className="empty-state">
            <p>Aucun cours trouvé</p>
            <button className="btn-secondary" onClick={handleCreateCourse}>
              Créer votre premier cours
            </button>
          </div>
        ) : (
          <table className="courses-table">
            <thead>
              <tr>
                <th>Titre</th>
                <th>Matière</th>
                <th>Niveau</th>
                <th>Visibilité</th>
                <th>Date</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {filteredCours.map((course, idx) => (
                <motion.tr
                  key={course.id}
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: idx * 0.05 }}
                >
                  <td className="course-title">{course.titre}</td>
                  <td>{course.matiere?.nom || '-'}</td>
                  <td>{course.niveau || '-'}</td>
                  <td>
                    <span className={`badge ${course.visibilite?.toLowerCase()}`}>
                      {course.visibilite === 'PUBLIC' ? 'Public' : 'Privé'}
                    </span>
                  </td>
                  <td className="text-muted">
                    {new Date(course.datePublication).toLocaleDateString('fr-FR')}
                  </td>
                  <td className="actions">
                    <button
                      className="btn-icon"
                      onClick={() => handleEditCourse(course)}
                      title="Éditer"
                    >
                      <Edit2 size={18} />
                    </button>
                    <button
                      className="btn-icon"
                      onClick={() => handleDeleteCourse(course.id)}
                      title="Supprimer"
                    >
                      <Trash2 size={18} />
                    </button>
                    <button
                      className="btn-icon"
                      title="Distribuer"
                    >
                      <Share2 size={18} />
                    </button>
                  </td>
                </motion.tr>
              ))}
            </tbody>
          </table>
        )}
      </motion.div>

      {/* Modal Cours */}
      {showModal && (
        <CourseModal
          isOpen={showModal}
          onClose={() => setShowModal(false)}
          onSave={handleSaveCourse}
          formData={courseFormData}
          onFormChange={handleFormChange}
          matieres={matieres}
          isEditing={!!editingCourse}
          loading={loading}
        />
      )}
    </motion.div>
  );
};

/**
 * Modal pour créer/éditer un cours
 */
const CourseModal = ({
  isOpen,
  onClose,
  onSave,
  formData,
  onFormChange,
  matieres,
  isEditing,
  loading
}) => {
  if (!isOpen) return null;

  return (
    <div className="modal-overlay" onClick={onClose}>
      <motion.div
        className="modal-content"
        onClick={(e) => e.stopPropagation()}
        initial={{ scale: 0.9, opacity: 0 }}
        animate={{ scale: 1, opacity: 1 }}
      >
        <h3>{isEditing ? 'Éditer le cours' : 'Nouveau cours'}</h3>

        <div className="form-group">
          <label>Titre du cours *</label>
          <input
            type="text"
            name="titre"
            value={formData.titre}
            onChange={onFormChange}
            placeholder="Entrez le titre"
          />
        </div>

        <div className="form-group">
          <label>Matière *</label>
          <select
            name="matiereId"
            value={formData.matiereId}
            onChange={onFormChange}
          >
            <option value="">Sélectionnez une matière</option>
            {matieres.map(m => (
              <option key={m.id} value={m.id}>{m.nom}</option>
            ))}
          </select>
        </div>

        <div className="form-row">
          <div className="form-group">
            <label>Niveau</label>
            <input
              type="text"
              name="niveau"
              value={formData.niveau}
              onChange={onFormChange}
              placeholder="L1, L2, M1, etc."
            />
          </div>

          <div className="form-group">
            <label>Session</label>
            <select
              name="session"
              value={formData.session}
              onChange={onFormChange}
            >
              <option value="HARMATTAN">Harmattan</option>
              <option value="MOUSSON">Mousson</option>
            </select>
          </div>
        </div>

        <div className="form-group">
          <label>Visibilité</label>
          <select
            name="visibilite"
            value={formData.visibilite}
            onChange={onFormChange}
          >
            <option value="PRIVE">Privé</option>
            <option value="PUBLIC">Public</option>
          </select>
        </div>

        <div className="modal-actions">
          <button className="btn-secondary" onClick={onClose} disabled={loading}>
            Annuler
          </button>
          <button
            className="btn-primary"
            onClick={onSave}
            disabled={loading || !formData.titre}
          >
            {loading ? <Loader className="spinner" size={20} /> : null}
            {loading ? 'Enregistrement...' : 'Enregistrer'}
          </button>
        </div>
      </motion.div>
    </div>
  );
};

export default VueGestionCours;
