import React from 'react';

/**
 * Logo REVISIA-H24 - Utilisé partout dans l'application
 * Header, menu, splash screen, etc.
 */
const RevisiaLogo = ({ size = 'medium', variant = 'full', className = '' }) => {
  const sizes = {
    small: { width: '40px', height: '40px', fontSize: '0.8rem' },
    medium: { width: '60px', height: '60px', fontSize: '1.2rem' },
    large: { width: '100px', height: '100px', fontSize: '2rem' },
    xlarge: { width: '140px', height: '140px', fontSize: '3.5rem' }
  };

  const style = sizes[size] || sizes.medium;

  if (variant === 'icon') {
    // Juste le cercle avec points
    return (
      <svg
        viewBox="0 0 120 120"
        width={style.width}
        height={style.height}
        className={className}
      >
        <circle cx="60" cy="60" r="50" fill="none" stroke="#1D4ED8" strokeWidth="3" />
        <circle cx="60" cy="10" r="5" fill="#F97316" />
        <circle cx="110" cy="60" r="5" fill="#F97316" />
        <circle cx="60" cy="110" r="5" fill="#F97316" />
        <circle cx="10" cy="60" r="5" fill="#F97316" />
      </svg>
    );
  }

  if (variant === 'text-only') {
    // Juste le texte
    return (
      <div
        style={{
          fontSize: style.fontSize,
          fontWeight: '900',
          letterSpacing: '-0.05em',
          display: 'flex',
          alignItems: 'baseline',
          gap: '0.25em'
        }}
        className={className}
      >
        <span style={{ color: '#1D4ED8' }}>REVISIA</span>
        <span style={{ color: '#F97316', letterSpacing: '0.05em' }}>H24</span>
      </div>
    );
  }

  // Full: icon + text
  return (
    <div
      style={{
        display: 'flex',
        alignItems: 'center',
        gap: '0.75rem',
        width: 'fit-content'
      }}
      className={className}
    >
      {/* Logo circulaire */}
      <svg
        viewBox="0 0 120 120"
        width={style.width}
        height={style.height}
        style={{ flexShrink: 0 }}
      >
        <circle cx="60" cy="60" r="50" fill="none" stroke="#1D4ED8" strokeWidth="3" />
        <circle cx="60" cy="10" r="5" fill="#F97316" />
        <circle cx="110" cy="60" r="5" fill="#F97316" />
        <circle cx="60" cy="110" r="5" fill="#F97316" />
        <circle cx="10" cy="60" r="5" fill="#F97316" />
      </svg>

      {/* Texte */}
      <div style={{ fontSize: style.fontSize, fontWeight: '900', letterSpacing: '-0.05em' }}>
        <span style={{ color: '#1D4ED8' }}>REVISIA</span>
        <span style={{ color: '#F97316', letterSpacing: '0.05em', marginLeft: '0.25em' }}>H24</span>
      </div>
    </div>
  );
};

export default RevisiaLogo;
