import React, { useState, useEffect, useCallback } from 'react';
import { useToast } from '../../hooks/useToast';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Plus, FileUp, Sparkles, BookOpen, Calendar, Eye, Loader,
  X, BarChart3, FileText, CheckCircle, AlertCircle, RefreshCw
} from 'lucide-react';
import { epreuveAPI, academicAPI, submissionsAPI } from '../../services/api';

const NIVEAUX    = ['L1', 'L2', 'L3', 'M1', 'M2', 'D1', 'D2', 'D3'];
const SESSIONS   = [{ val: 'HARMATTAN', label: 'Harmattan (1er semestre)' }, { val: 'MOUSSON', label: 'Mousson (2e semestre)' }];
const TYPE_ACCES = [{ val: 'GRATUIT', label: 'Gratuit (accès libre)' }, { val: 'PAYANT', label: 'Payant' }];
const ANNEE_NOW  = new Date().getFullYear();

/**
 * VueEvaluations — Gestion des épreuves/examens du professeur
 * Permet de : publier, analyser (IA), générer corrigé (IA), voir soumissions
 */
const VueEvaluations = ({ user, matieres = [], onRefresh }) => {
  const { showToast, ToastUI } = useToast();
  const [epreuves, setEpreuves]       = useState([]);
  const [loading, setLoading]         = useState(true);
  const [showForm, setShowForm]       = useState(false);
  const [publishing, setPublishing]   = useState(false);
  const [aiLoading, setAiLoading]     = useState({});
  const [statsMap, setStatsMap]       = useState({});
  const [allMatieres, setAllMatieres] = useState(matieres);

  const [form, setForm] = useState({
    titre:            '',
    annee:            ANNEE_NOW,
    session:          'HARMATTAN',
    matiereId:        '',
    typeAcces:        'GRATUIT',
    prix:             0,
    identifiantPublic: '',
    fichier:          null,
  });

  // ── Charger les épreuves ─────────────────────────────────
  const loadEpreuves = useCallback(async () => {
    try {
      setLoading(true);
      const [eprRes, matRes] = await Promise.all([
        epreuveAPI.getAll().catch(() => ({ data: [] })),
        allMatieres.length > 0
          ? Promise.resolve({ data: allMatieres })
          : academicAPI.getMatieres().catch(() => ({ data: [] })),
      ]);
      setEpreuves(eprRes.data || []);
      if (allMatieres.length === 0) setAllMatieres(matRes.data || []);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => { loadEpreuves(); }, [loadEpreuves]);

  // ── Générer identifiant automatique ─────────────────────
  const generateId = () => {
    const slug = form.titre
      .toLowerCase()
      .normalize('NFD')
      .replace(/[̀-ͯ]/g, '')
      .replace(/[^a-z0-9]+/g, '-')
      .slice(0, 20);
    return `${slug}-${form.annee}-${Math.random().toString(36).slice(2, 6).toUpperCase()}`;
  };

  // ── Publier l'épreuve ────────────────────────────────────
  const handlePublish = async () => {
    if (!form.titre.trim())  return showToast('Titre requis', 'error');
    if (!form.matiereId)     return showToast('Matière requise', 'error');
    if (!form.fichier)       return showToast('Fichier requis', 'error');

    const identifiant = form.identifiantPublic.trim() || generateId();

    try {
      setPublishing(true);
      const fd = new FormData();
      fd.append('fichier', form.fichier);
      fd.append('identifiantPublic', identifiant);
      fd.append('titre',      form.titre);
      fd.append('annee',      form.annee);
      fd.append('session',    form.session);
      fd.append('matiereId',  form.matiereId);
      fd.append('typeAcces',  form.typeAcces);
      fd.append('prix',       form.prix || 0);

      await epreuveAPI.publish(fd);
      showToast('Épreuve publiée avec succès !');
      setShowForm(false);
      setForm({
        titre: '', annee: ANNEE_NOW, session: 'HARMATTAN',
        matiereId: '', typeAcces: 'GRATUIT', prix: 0,
        identifiantPublic: '', fichier: null,
      });
      loadEpreuves();
      onRefresh?.();
    } catch (err) {
      console.error(err);
      showToast(err.response?.data?.error || 'Erreur lors de la publication', 'error');
    } finally {
      setPublishing(false);
    }
  };

  // ── IA : analyser ───────────────────────────────────────
  const handleAnalyse = async (identifiant) => {
    try {
      setAiLoading(prev => ({ ...prev, [identifiant]: 'analyse' }));
      await epreuveAPI.analyser(identifiant);
      showToast('Analyse IA lancée — les résultats seront disponibles sous peu');
    } catch (err) {
      showToast('Erreur lors de l\'analyse', 'error');
    } finally {
      setAiLoading(prev => ({ ...prev, [identifiant]: null }));
    }
  };

  // ── IA : générer corrigé ────────────────────────────────
  const handleGenererCorrige = async (identifiant) => {
    try {
      setAiLoading(prev => ({ ...prev, [identifiant]: 'corrige' }));
      await epreuveAPI.genererCorrige(identifiant);
      showToast('Corrigé IA généré ! Vérifiez dans le détail de l\'épreuve.');
      loadEpreuves();
    } catch (err) {
      showToast('Erreur lors de la génération du corrigé', 'error');
    } finally {
      setAiLoading(prev => ({ ...prev, [identifiant]: null }));
    }
  };

  // ── Charger stats soumissions ────────────────────────────
  const loadStats = async (epreuveId) => {
    if (statsMap[epreuveId]) return;
    try {
      const res = await submissionsAPI.getSubmissionsEpreuve(epreuveId).catch(() => ({ data: [] }));
      const list = res.data || [];
      setStatsMap(prev => ({
        ...prev,
        [epreuveId]: { total: list.length, corriges: list.filter(s => s.statut === 'CORRIGE').length }
      }));
    } catch { /* silencieux */ }
  };

  const handleFormChange = e => {
    const { name, value } = e.target;
    setForm(prev => ({ ...prev, [name]: value }));
  };

  if (loading) {
    return (
      <div className="center-loader">
        <Loader className="spinner" size={32} style={{ color: '#0EA5E9' }} />
        <p>Chargement des épreuves…</p>
      </div>
    );
  }

  return (
    <motion.div
      className="vue-evaluations"
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
    >
      {ToastUI}

      {/* ── Header ── */}
      <div className="vue-header">
        <h2>Exercices &amp; Évaluations</h2>
        <div style={{ display: 'flex', gap: 10 }}>
          <button className="btn-secondary" onClick={loadEpreuves} title="Rafraîchir">
            <RefreshCw size={16} />
          </button>
          <button className="btn-primary" onClick={() => setShowForm(true)}>
            <Plus size={18} /> Publier une Épreuve
          </button>
        </div>
      </div>

      {/* ── Statistiques rapides ── */}
      <div className="eval-stats-row">
        <div className="eval-stat-chip">
          <FileText size={16} />
          <span><strong>{epreuves.length}</strong> épreuve{epreuves.length > 1 ? 's' : ''}</span>
        </div>
        <div className="eval-stat-chip green">
          <CheckCircle size={16} />
          <span><strong>{epreuves.filter(e => e.corrigeUrl).length}</strong> avec corrigé</span>
        </div>
        <div className="eval-stat-chip orange">
          <Sparkles size={16} />
          <span>IA disponible</span>
        </div>
      </div>

      {/* ── Liste des épreuves ── */}
      {epreuves.length === 0 ? (
        <div className="empty-state">
          <BarChart3 size={48} />
          <p>Aucune épreuve publiée</p>
          <button className="btn-secondary" onClick={() => setShowForm(true)}>
            Publier votre première épreuve
          </button>
        </div>
      ) : (
        <div className="epreuves-list">
          {epreuves.map((ep, idx) => (
            <EpreuveCard
              key={ep.identifiantPublic || ep.id}
              epreuve={ep}
              idx={idx}
              aiLoading={aiLoading}
              stats={statsMap[ep.id]}
              onLoadStats={() => loadStats(ep.id)}
              onAnalyse={() => handleAnalyse(ep.identifiantPublic)}
              onCorrige={() => handleGenererCorrige(ep.identifiantPublic)}
            />
          ))}
        </div>
      )}

      {/* ── Formulaire de publication ── */}
      <AnimatePresence>
        {showForm && (
          <PublishModal
            form={form}
            onFormChange={handleFormChange}
            setForm={setForm}
            matieres={allMatieres}
            publishing={publishing}
            onPublish={handlePublish}
            onClose={() => setShowForm(false)}
          />
        )}
      </AnimatePresence>
    </motion.div>
  );
};

/* ════════════════════════════════════════════════════════════
   CARTE ÉPREUVE
════════════════════════════════════════════════════════════ */
const EpreuveCard = ({ epreuve, idx, aiLoading, stats, onLoadStats, onAnalyse, onCorrige }) => {
  const [expanded, setExpanded] = useState(false);
  const id = epreuve.identifiantPublic || epreuve.id;

  const toggleExpand = () => {
    if (!expanded && !stats) onLoadStats();
    setExpanded(p => !p);
  };

  return (
    <motion.div
      className="epreuve-card"
      initial={{ opacity: 0, y: 12 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ delay: idx * 0.05 }}
    >
      {/* En-tête */}
      <div className="epreuve-card-header" onClick={toggleExpand}>
        <div className="epreuve-meta">
          <BookOpen size={16} />
          <div>
            <h3 className="epreuve-titre">{epreuve.titre}</h3>
            <span className="epreuve-info">
              {epreuve.matiere?.nom || '—'} · {epreuve.session || '—'} {epreuve.annee || '—'}
              {epreuve.typeAcces === 'GRATUIT'
                ? ' · 🆓 Gratuit'
                : ` · 💰 ${epreuve.prix ?? 0} FCFA`}
            </span>
          </div>
        </div>
        <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
          {epreuve.corrigeUrl && (
            <span className="badge green" title="Corrigé disponible">✓ Corrigé</span>
          )}
          <span style={{ color: '#475569', fontSize: '0.72rem' }}>
            {expanded ? '▲' : '▼'}
          </span>
        </div>
      </div>

      {/* Contenu déroulant */}
      <AnimatePresence>
        {expanded && (
          <motion.div
            className="epreuve-card-body"
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: 'auto', opacity: 1 }}
            exit={{ height: 0, opacity: 0 }}
            transition={{ duration: 0.25 }}
          >
            {/* Lien PDF */}
            {epreuve.fichierUrl && (
              <a
                href={epreuve.fichierUrl}
                target="_blank"
                rel="noopener noreferrer"
                className="epreuve-link"
              >
                <Eye size={14} /> Voir le sujet (PDF)
              </a>
            )}

            {/* Stats soumissions */}
            {stats ? (
              <div className="epreuve-stats">
                <span>📥 {stats.total} soumission{stats.total > 1 ? 's' : ''}</span>
                <span>✅ {stats.corriges} corrigé{stats.corriges > 1 ? 's' : ''}</span>
              </div>
            ) : (
              <div className="epreuve-stats loading-stats">
                <Loader size={12} className="spinner" /> Chargement des statistiques…
              </div>
            )}

            {/* Actions IA */}
            <div className="epreuve-actions">
              <button
                className="btn-ai"
                onClick={onAnalyse}
                disabled={!!aiLoading[id]}
                title="Analyser le sujet avec l'IA"
              >
                {aiLoading[id] === 'analyse'
                  ? <Loader size={14} className="spinner" />
                  : <Sparkles size={14} />
                }
                Analyser (IA)
              </button>

              <button
                className="btn-ai secondary"
                onClick={onCorrige}
                disabled={!!aiLoading[id]}
                title="Générer un corrigé automatique avec l'IA"
              >
                {aiLoading[id] === 'corrige'
                  ? <Loader size={14} className="spinner" />
                  : <FileText size={14} />
                }
                Générer Corrigé (IA)
              </button>

              <span
                style={{
                  fontSize: '0.7rem', color: '#475569',
                  padding: '4px 8px', borderRadius: 6,
                  background: '#f8fafc',
                  display: 'flex', alignItems: 'center', gap: 4
                }}
              >
                <Calendar size={12} />
                ID : <code style={{ fontFamily: 'monospace' }}>{id}</code>
              </span>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </motion.div>
  );
};

/* ════════════════════════════════════════════════════════════
   MODAL PUBLICATION
════════════════════════════════════════════════════════════ */
const PublishModal = ({ form, onFormChange, setForm, matieres, publishing, onPublish, onClose }) => {
  const [fileName, setFileName] = useState('');

  const handleFile = e => {
    const f = e.target.files?.[0];
    if (!f) return;
    setForm(prev => ({ ...prev, fichier: f }));
    setFileName(f.name);
  };

  return (
    <motion.div
      className="modal-overlay"
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      onClick={onClose}
    >
      <motion.div
        className="modal-content modal-large"
        onClick={e => e.stopPropagation()}
        initial={{ scale: 0.9, opacity: 0, y: 20 }}
        animate={{ scale: 1, opacity: 1, y: 0 }}
        exit={{ scale: 0.9, opacity: 0, y: 20 }}
      >
        {/* Header */}
        <div className="modal-header">
          <h3>📤 Publier une épreuve / examen</h3>
          <button className="btn-icon" onClick={onClose}><X size={20} /></button>
        </div>

        <div className="modal-body-scroll">
          {/* Upload fichier */}
          <div className="form-group">
            <label>Fichier (PDF, Word…) <span className="required">*</span></label>
            <label className="file-upload-zone">
              <FileUp size={24} style={{ color: '#0EA5E9' }} />
              <span>{fileName || 'Cliquez pour sélectionner un fichier'}</span>
              <input type="file" accept=".pdf,.doc,.docx" onChange={handleFile} style={{ display: 'none' }} />
            </label>
          </div>

          {/* Titre */}
          <div className="form-group">
            <label>Titre de l'épreuve <span className="required">*</span></label>
            <input
              type="text"
              name="titre"
              value={form.titre}
              onChange={onFormChange}
              placeholder="Ex: Examen final Algorithmique – Licence 2"
            />
          </div>

          {/* Matière + Session */}
          <div className="form-row">
            <div className="form-group">
              <label>Matière <span className="required">*</span></label>
              <select name="matiereId" value={form.matiereId} onChange={onFormChange}>
                <option value="">— Sélectionner —</option>
                {matieres.map(m => (
                  <option key={m.id} value={m.id}>{m.nom}</option>
                ))}
              </select>
            </div>
            <div className="form-group">
              <label>Session</label>
              <select name="session" value={form.session} onChange={onFormChange}>
                {SESSIONS.map(s => <option key={s.val} value={s.val}>{s.label}</option>)}
              </select>
            </div>
          </div>

          {/* Année + TypeAcces */}
          <div className="form-row">
            <div className="form-group">
              <label>Année</label>
              <input
                type="number"
                name="annee"
                value={form.annee}
                onChange={onFormChange}
                min={2010}
                max={ANNEE_NOW + 1}
              />
            </div>
            <div className="form-group">
              <label>Type d'accès</label>
              <select name="typeAcces" value={form.typeAcces} onChange={onFormChange}>
                {TYPE_ACCES.map(t => <option key={t.val} value={t.val}>{t.label}</option>)}
              </select>
            </div>
          </div>

          {/* Prix si payant */}
          {form.typeAcces === 'PAYANT' && (
            <div className="form-group">
              <label>Prix (FCFA)</label>
              <input
                type="number"
                name="prix"
                value={form.prix}
                onChange={onFormChange}
                min={0}
                step={100}
              />
            </div>
          )}

          {/* Identifiant public (optionnel) */}
          <div className="form-group">
            <label>Identifiant public <small style={{ fontWeight: 400, color: '#475569' }}>(optionnel — généré auto si vide)</small></label>
            <input
              type="text"
              name="identifiantPublic"
              value={form.identifiantPublic}
              onChange={onFormChange}
              placeholder="Ex: algo-l2-2024-H"
            />
          </div>

          <div className="info-box" style={{ background: 'rgba(14,165,233,0.08)', border: '1px solid rgba(14,165,233,0.2)', borderRadius: 10, padding: '10px 14px', fontSize: '0.78rem', color: '#7DD3FC' }}>
            <AlertCircle size={14} style={{ marginRight: 6, verticalAlign: 'middle' }} />
            Après publication, vous pourrez utiliser l'IA pour analyser le sujet ou générer un corrigé automatiquement.
          </div>
        </div>

        {/* Actions */}
        <div className="modal-actions">
          <button className="btn-secondary" onClick={onClose} disabled={publishing}>Annuler</button>
          <button className="btn-primary" onClick={onPublish} disabled={publishing || !form.fichier || !form.titre}>
            {publishing ? <Loader className="spinner" size={18} /> : <FileUp size={18} />}
            {publishing ? 'Publication…' : 'Publier l\'épreuve'}
          </button>
        </div>
      </motion.div>
    </motion.div>
  );
};

export default VueEvaluations;
