import React, { useState } from 'react';
import { motion } from 'framer-motion';
import Header from './Header';
import Sidebar from './Sidebar';
import DashboardBackButton from './DashboardBackButton';
import '../styles/dashboard-layout.css';

/**
 * Layout Principal REVISIA H24
 * ─ Header avec logo
 * ─ Sidebar avec menu + profil utilisateur
 * ─ Bouton retour visible en haut si navigation prop fournie
 * ─ Zone de contenu responsive
 *
 * Props :
 *   user            — objet utilisateur connecté
 *   title           — titre affiché dans le header
 *   menuItems       — items du menu sidebar
 *   activeMenuKey   — clé de la vue active
 *   onMenuItemClick — callback quand on clique un item
 *   onLogout        — callback déconnexion
 *   showNotifications — booléen
 *   navigation      — { canGoBack, onBack, backLabel }
 *   children        — contenu du dashboard
 */
const DashboardLayout = ({
  user,
  title,
  children,
  menuItems = [],
  activeMenuKey = null,
  onMenuItemClick = () => {},
  onLogout = () => {},
  showNotifications = true,
  navigation = null,
}) => {
  const [sidebarOpen, setSidebarOpen] = useState(false);

  const handleMenuClick = (item) => {
    onMenuItemClick(item);
    setSidebarOpen(false);
  };

  return (
    <div className="dashboard-layout">
      {/* Header */}
      <Header
        user={user}
        title={title}
        showNotifications={showNotifications}
        onMenuClick={() => setSidebarOpen(prev => !prev)}
        onLogout={onLogout}
      />

      {/* Sidebar avec profil */}
      <Sidebar
        isOpen={sidebarOpen}
        onClose={() => setSidebarOpen(false)}
        user={user}
        menuItems={menuItems.map(item => ({
          ...item,
          onClick: () => handleMenuClick(item),
        }))}
        activeItem={activeMenuKey}
      />

      {/* Contenu principal */}
      <motion.main
        className="dashboard-main-content"
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ duration: 0.25 }}
      >
        {/* ── Bouton retour en haut ── */}
        {navigation?.canGoBack && (
          <div className="back-button-bar">
            <DashboardBackButton
              label={navigation.backLabel || '← Retour'}
              onBack={navigation.onBack}
              variant="light"
            />
          </div>
        )}

        {/* ── Contenu dashboard ── */}
        <div className="dashboard-content-wrapper">
          {children}
        </div>
      </motion.main>
    </div>
  );
};

export default DashboardLayout;
